mod tests {
    use super::*;

    // Step 1: Test the basic examples from the problem
    #[test]
    fn test_look_and_say_examples() {
        assert_eq!(look_and_say("1"), "11");
        assert_eq!(look_and_say("11"), "21");
        assert_eq!(look_and_say("21"), "1211");
        assert_eq!(look_and_say("1211"), "111221");
        assert_eq!(look_and_say("111221"), "312211");
    }
    
    // Step 2: Test edge case - empty string
    #[test]
    fn test_look_and_say_empty() {
        assert_eq!(look_and_say(""), "");
    }
    
    // Step 3: Test edge case - single character
    #[test]
    fn test_look_and_say_single() {
        assert_eq!(look_and_say("5"), "15");
    }
    
    // Step 4: Test multiple groups of different characters
    #[test]
    fn test_look_and_say_multiple_groups() {
        // "1223" = one 1, two 2s, one 3 = "112213"
        assert_eq!(look_and_say("1223"), "112213");
    }
}

